import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.map.js";
import { schedule_game } from "@/graphql/mutations";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "../SnackBar.vue";
export default {
  props: {
    DialogScheduleCustomGame: Boolean,
    StoreObj: Object
  },
  components: {
    SnackBar
  },
  data: () => ({
    frequency: "WEEKLY",
    days: "MONDAY",
    count: "3",
    dateMenu: false,
    timeMenu: false,
    loading: false,
    recurring: false,
    selectedDate: new Date(),
    selectedTime: new Date().toTimeString().slice(0, 5),
    SnackBarComponent: {},
    FrequencyItems: [{
      title: "Weekly",
      value: "WEEKLY"
    }, {
      title: "Monthly",
      value: "MONTHLY"
    }, {
      title: "Daily",
      value: "DAILY"
    }],
    DayItems: [{
      title: "Monday",
      value: "MONDAY"
    }, {
      title: "Tuesday",
      value: "TUESDAY"
    }, {
      title: "Wednesday",
      value: "WEDNESDAY"
    }, {
      title: "Thursday",
      value: "THURSDAY"
    }, {
      title: "Friday",
      value: "FRIDAY"
    }, {
      title: "Saturday",
      value: "SATURDAY"
    }, {
      title: "Sunday",
      value: "SUNDAY"
    }],
    CountItems: [{
      title: "3",
      value: "3"
    }, {
      title: "5",
      value: "5"
    }, {
      title: "10",
      value: "10"
    }, {
      title: "20",
      value: "20"
    }, {
      title: "50",
      value: "50"
    }]
  }),
  computed: {
    formattedDate() {
      if (!this.selectedDate) return "";
      return this.formatDate(this.selectedDate);
    },
    formattedTime() {
      if (!this.selectedTime) return "";
      const [h, m] = this.selectedTime.split(":");
      return new Date(0, 0, 0, h, m).toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit"
      });
    },
    gameScheduledEpoch() {
      const [hours, minutes] = this.selectedTime.split(":").map(Number);
      const date = new Date(this.selectedDate);
      date.setHours(hours, minutes, 0, 0);
      return Math.floor(date.getTime() / 1000);
    },
    recurringScheduleTime() {
      if (!this.recurring || !this.selectedTime) return null;
      const [hour24, minute] = this.selectedTime.split(":").map(Number);
      const timeStr = `${String(hour24).padStart(2, "0")}:${String(minute).padStart(2, "0")}`;
      return timeStr;
    }
  },
  methods: {
    async ScheduleGame() {
      this.loading = true;
      try {
        const input = {
          splay_category_id: this.StoreObj.splay_category_id,
          game_scheduled_time: this.gameScheduledEpoch,
          leaderboard_count: parseInt(this.count)
        };
        if (this.recurring) {
          input.reccuring_game = true;
          input.reccuring_schedule = this.frequency;
          input.reccuring_day = this.days;
          input.reccuring_schedule_time = this.recurringScheduleTime;
        }
        const result = await API.graphql(graphqlOperation(schedule_game, {
          input
        }));
        const resultObj = JSON.parse(result.data.schedule_game);
        if (resultObj.Status === "SUCCESS") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: resultObj.message
          };
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: resultObj.Message
          };
        }
        this.DialogScheduleCustomGameEmit(2);
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Failed to schedule game, try again"
        };
      } finally {
        this.loading = false;
      }
    },
    DialogScheduleCustomGameEmit(Toggle) {
      this.$emit("clicked", Toggle);
    },
    formatDate(selectedDate) {
      const date = new Date(selectedDate);
      return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
    },
    allowedDatesByDay(date) {
      if (!this.recurring) return true;
      const dayMap = {
        SUNDAY: 0,
        MONDAY: 1,
        TUESDAY: 2,
        WEDNESDAY: 3,
        THURSDAY: 4,
        FRIDAY: 5,
        SATURDAY: 6
      };
      const selectedDayNumber = dayMap[this.days];
      const dateObj = new Date(date);
      return dateObj.getDay() === selectedDayNumber;
    }
  }
};
